'use client';

import Link from 'next/link';
import { Button } from '@/components/ui/button';
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from '@/components/ui/card';
import { ArrowUpRight, PlusCircle } from 'lucide-react';
import { Badge } from '@/components/ui/badge';
import { useUser, useFirestore, useCollection, useMemoFirebase } from '@/firebase';
import { collection } from 'firebase/firestore';
import type { Project } from '@/lib/types';
import { Skeleton } from '@/components/ui/skeleton';

function StatsCard({ isLoading, projects }: { isLoading: boolean, projects: Project[] | null }) {
  if (isLoading) {
    return (
      <Card>
        <CardHeader>
          <CardTitle>Quick Stats</CardTitle>
        </CardHeader>
        <CardContent className="grid gap-4">
          {[...Array(3)].map((_, i) => (
            <div className="flex items-center" key={i}>
              <div>
                <Skeleton className="h-4 w-[100px] mb-2" />
                <Skeleton className="h-7 w-[60px]" />
              </div>
            </div>
          ))}
        </CardContent>
      </Card>
    )
  }

  const totalProjects = projects?.length || 0;
  const totalBudget = projects?.reduce((acc, project) => acc + project.totalBudget, 0) || 0;
  const averageBudget = totalProjects > 0 ? totalBudget / totalProjects : 0;
  const now = new Date();
  const firstDayOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
  const newThisMonth = projects?.filter(p => new Date(p.createdDate) >= firstDayOfMonth).length || 0;

  const currencyFormatter = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 0, maximumFractionDigits: 0 });

  return (
    <Card>
      <CardHeader>
        <CardTitle>Quick Stats</CardTitle>
      </CardHeader>
      <CardContent className="grid gap-4">
        <div className="flex items-center">
          <div>
            <p className="text-sm font-medium text-muted-foreground">
              Total Projects
            </p>
            <p className="text-2xl font-bold">{totalProjects}</p>
          </div>
        </div>
        <div className="flex items-center">
          <div>
            <p className="text-sm font-medium text-muted-foreground">
              Avg. Budget
            </p>
            <p className="text-2xl font-bold">{currencyFormatter.format(averageBudget)}</p>
          </div>
        </div>
        <div className="flex items-center">
          <div>
            <p className="text-sm font-medium text-muted-foreground">
              New this month
            </p>
            <p className="text-2xl font-bold">+{newThisMonth}</p>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

function RecentProjectsCard({ isLoading, projects }: { isLoading: boolean, projects: Project[] | null }) {
    const recentProjects = projects
    ? [...projects]
        .sort((a, b) => new Date(b.createdDate).getTime() - new Date(a.createdDate).getTime())
        .slice(0, 3)
    : [];

  return (
    <Card>
      <CardHeader className="flex flex-row items-center">
        <div className="grid gap-2">
          <CardTitle>Recent Projects</CardTitle>
          <CardDescription>
            Here are the latest estimates you&apos;ve created.
          </CardDescription>
        </div>
        <Button asChild size="sm" className="ml-auto gap-1">
          <Link href="/projects">
            View All
            <ArrowUpRight className="h-4 w-4" />
          </Link>
        </Button>
      </CardHeader>
      <CardContent>
        {isLoading ? (
          <div className="space-y-4">
            {[...Array(3)].map((_, i) => (
                <div key={i} className="flex items-center justify-between rounded-lg border p-3">
                    <div>
                        <Skeleton className="h-5 w-[200px] mb-2" />
                        <Skeleton className="h-4 w-[100px]" />
                    </div>
                    <Skeleton className="h-6 w-[80px]" />
                </div>
            ))}
          </div>
        ) : recentProjects.length > 0 ? (
             <div className="space-y-4">
            {recentProjects.map((project) => (
              <div
                key={project.id}
                className="flex items-center justify-between rounded-lg border p-3"
              >
                <div>
                  <p className="font-semibold">{project.projectName}</p>
                  <p className="text-sm text-muted-foreground">
                    Created {new Date(project.createdDate).toLocaleDateString()}
                  </p>
                </div>
                <Badge variant="secondary">{new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 0 }).format(project.totalBudget)}</Badge>
              </div>
            ))}
          </div>
        ) : (
            <div className="text-center text-muted-foreground py-8">
                You haven&apos;t created any projects yet.
            </div>
        )}
      </CardContent>
    </Card>
  );
}

export default function DashboardPage() {
  const { user, isUserLoading } = useUser();
  const firestore = useFirestore();

  const projectsQuery = useMemoFirebase(() => {
    if (!user) return null;
    return collection(firestore, 'users', user.uid, 'projectEstimates');
  }, [firestore, user]);

  const { data: projects, isLoading: areProjectsLoading } = useCollection<Project>(projectsQuery);

  const isLoading = isUserLoading || areProjectsLoading;

  return (
    <div className="flex-1 space-y-4 p-4 md:p-8 pt-6">
      <div className="flex items-center justify-between space-y-2">
        <h1 className="text-3xl font-bold tracking-tight font-headline">Dashboard</h1>
      </div>
      <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
        <Card className="col-span-1 lg:col-span-2">
          <CardHeader>
            <CardTitle>Welcome to RenoAI!</CardTitle>
            <CardDescription>
              Your intelligent partner for commercial renovation budgeting.
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            <p className="text-muted-foreground">
              Ready to start planning your next commercial project? Get a detailed,
              AI-powered budget estimate in minutes. Just describe your
              project, and we&apos;ll handle the rest.
            </p>
            <Button asChild>
              <Link href="/estimate">
                <PlusCircle className="mr-2 h-4 w-4" />
                Create New Estimate
              </Link>
            </Button>
          </CardContent>
        </Card>
        <StatsCard isLoading={isLoading} projects={projects} />
      </div>
      <RecentProjectsCard isLoading={isLoading} projects={projects} />
    </div>
  );
}
